ROOT=Path('/Users/n/androidhit')
def git(*args):return subprocess.check_output(['git',*args],cwd=ROOT,text=True)
allfiles=set(git('ls-files','--cached','--others','--exclude-standard').splitlines())
changed=set(git('diff','--name-only','HEAD','--').splitlines())|set(git('ls-files','--others','--exclude-standard').splitlines())
files=sorted(p for p in allfiles if p.lower().endswith(('.md','.html')) and (ROOT/p).is_file())
def nofences(s):
 out=[];inside=False;fence=''
 for l in s.splitlines(keepends=True):
  m=re.match(r'^\s*(`{3,}|~{3,})',l)
  if m:
   if not inside:inside=True;fence=m[1][0]
   elif m[1][0]==fence:inside=False
   out.append('\n');continue
  out.append('\n' if inside else l)
 return ''.join(out)
class Links(HTMLParser):
 def __init__(self):super().__init__(convert_charrefs=True);self.links=[];self.anchors=set()
 def handle_starttag(self,tag,attrs):
  d=dict(attrs)
  for key in ('id','name'):
   if d.get(key):self.anchors.add(d[key])
  for k in ('href','src','poster','data-src'):
   if d.get(k):self.links.append((d[k],self.getpos()[0],tag+'@'+k))
  if d.get('srcset'):
   for x in d['srcset'].split(','):
    if x.strip():self.links.append((x.strip().split()[0],self.getpos()[0],tag+'@srcset'))
