 if p.endswith('.md'):
  # Inline Markdown destinations; balanced parentheses allow literal path parentheses.
  for m in re.finditer(r'!?\[[^\]\n]*(?:\][^\]\n]*)?\]\(',clean):
   at=m.end();depth=1;end=at
   while end<len(clean) and depth:
    if clean[end]=='(' and (end==0 or clean[end-1]!='\\'):depth+=1
    if clean[end]==')' and (end==0 or clean[end-1]!='\\'):depth-=1
    end+=1
   if depth:continue
   val=clean[at:end-1].strip()
   if val.startswith('<') and '>' in val:val=val[1:val.index('>')]
   else:val=re.split(r'\s+[\"\']',val,maxsplit=1)[0].strip()
   links.append((val,clean.count('\n',0,m.start())+1,'markdown-destination'))
  for m in re.finditer(r'^\s{0,3}\[[^\]\n]+\]:\s*(<[^>]+>|\S+)',clean,re.M):
   links.append((m[1].strip('<>'),clean.count('\n',0,m.start())+1,'markdown-reference-definition'))
