 if suffix not in ('.md','.html'):return None
 _,a=parse(str(path),s)
 if suffix=='.md':
  duplicates=Counter()
  for l in nofences(s).splitlines():
   m=re.match(r'^\s{0,3}#{1,6}\s+(.+?)(?:\s+#+\s*)?$',l)
   if not m:continue
   text=re.sub(r'<[^>]*>','',m[1]);text=re.sub(r'!?\[([^\]]+)\]\([^)]*\)',r'\1',text);text=html.unescape(text).lower()
