  elif split.netloc=='raw.githubusercontent.com' and split.path.startswith(pre+'main/'):
   path=ROOT/unquote(split.path[len(pre+'main/'):]);mapping='own-github-main-mapped-locally'
  elif split.netloc in ('luma-drift-production.web.app','luma-drift-production.firebaseapp.com'):
   path=ROOT/'public'/unquote(split.path.lstrip('/'));mapping='own-hosting-route-mapped-locally'
  else:return None
 elif scheme and scheme!='file':return None
 else:
  rel=unquote(split.path)
  if not rel:path=ROOT/source
  elif rel.startswith('/'):
   path=(ROOT/'public'/rel.lstrip('/')) if source.startswith('public/') else Path(rel)
  else:path=ROOT/source;path=path.parent/rel
 path=path.resolve()
 if path.is_dir() and (path/'index.html').exists():path=path/'index.html'
 fragment=unquote(split.fragment)
 return path,fragment,mapping
entries=[];issues=[];sources=[];excluded=Counter();baseline_cache={}
for p in files:
