report={'checked_at_utc':datetime.now(timezone.utc).isoformat(),'head':git('rev-parse','HEAD').strip(),'method':{'network_used':False,'file_scope':'All tracked and nonignored untracked Markdown/HTML files, plus explicit classification of changed/new source documents. Report artifacts count in repository inventory but JSON/CSV/screenshots are not interpreted as HTML links.','resolution':'Markdown inline destinations and reference definitions, HTML href/src/srcset/poster/data-src; query stripped, URL decoded, public-root HTML paths and directory index.html supported. Own GitHub main/raw and production Hosting links map to local repository/public files only; no remote existence or deployment claim.','fragments':'HTML id/name and approximated GitHub Markdown heading slugs checked; fenced code ignored. Source text is not otherwise executed.','baseline':'Target strings present in HEAD source classified carried-forward; new targets are introduced. Missing pilot image curation is reported separately, never silently counted as current-byte native screenshots.','limitations':'No external URL/network, JS-generated URLs, CSS URL crawl or Markdown reference-use validity check; no prose/claim/legal review.'},'inventory':{'tracked_and_nonignored_untracked_paths':len(allfiles),'changed_or_untracked_paths':len(changed),'markdown_html_files':len(files),'changed_or_untracked_markdown_html':sum(p in changed for p in files)},'counts':{'local_destinations_checked':len(entries),'external_or_nonfile_destinations_excluded':sum(excluded.values()),'ok':sum(e['status']=='ok' for e in entries),'issues':len(issues),'introduced_issues':sum(not e.get('target_carried_from_HEAD',False) for e in issues),'local_destinations_in_changed_or_untracked_documents':sum(e['source_changed_or_untracked'] for e in entries),'introduced_targets_in_changed_or_untracked_documents':sum(e['source_changed_or_untracked'] and not e['target_carried_from_HEAD'] for e in entries),'carried_targets_in_changed_or_untracked_documents':sum(e['source_changed_or_untracked'] and e['target_carried_from_HEAD'] for e in entries),'historical_or_unchanged_source_issues':sum(e.get('target_carried_from_HEAD',False) or not e.get('source_changed_or_untracked',False) for e in issues),'missing_pilot_curated_artifact_destinations':sum(('pilot' in e.get('source','').lower() or 'pilot' in e.get('resolved','').lower()) and e.get('status')=='missing_file' for e in issues),'public_v19_png_destinations_unique':len({e['resolved'] for e in entries if e['source'].startswith('public/') and '/v1.9/' in e['resolved'] and e['resolved'].endswith('.png')})},'passed_all_resolved_local_destinations':not issues,'issues':issues,'sources':sources,'destinations':entries,'checker_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'checker_source':Path(__file__).read_text()}
output=ROOT/'docs/validation/v1.9/document-links.json';output.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
